  pos: { ikincil: ['barkodlu satış programı', 'bakkal programı', 'veresiye takip programı'], uzunKuyruk: ['terazi barkodu okuyan market programı', 'telefondan barkod okuyan satış programı', 'market stok takip programı'], altBaslik: 'Barkodlu satış programında kasadan stoğa her şey', paragraf: 'Bakkal programı veya veresiye takip programı arayan küçük işletmeler de aynı ekranı kullanır: barkod, terazi barkodu, veresiye ve parçalı ödeme hazırdır.', sss: [['Telefonla barkod okutabilir miyim?', 'Evet. Telefon veya tablet kamerasıyla barkod okunur. Kamera ile okuma tarayıcı kuralı gereği https adreste çalışır.']] },
  eticaret: { ikincil: ['hazır e-ticaret sitesi', 'pazaryeri entegrasyonu', 'e-ticaret yazılımı'], uzunKuyruk: ['trendyol stok senkronu', 'pazaryeri hakediş takibi', 'kendi markamla e-ticaret sitesi'], altBaslik: 'Hazır e-ticaret sitesi ve pazaryeri entegrasyonu bir arada', paragraf: 'E-ticaret yazılımı arayışınızda hem kendi mağazanızı hem pazaryeri kanallarınızı tek panelden yönetirsiniz; kanal bazında fiyat farkı ve stok tamponu tanımlayabilirsiniz.', sss: [['Pazaryeri hakedişimi nasıl takip ederim?', 'Hakediş mutabakatı ekranında komisyon, hizmet bedeli, kargo kesintisi ve ödeme vadesi birlikte görünür.']] },
